        try {
          await writeNew(temporary, raw);
          return await exportSellerClient({ openapi: temporary, out: target, provenance: { exportId } });
        } finally { await unlink(temporary).catch(error => { if (error.code !== 'ENOENT') throw error; }); }
        })();
