      current[key] = /^(?:0|[1-9]\d{0,4})$/.test(parts[i + 1]) ? [] : {};
    if (!object(current[key]) && !Array.isArray(current[key]))
      fail('SUPPLIER_POINTER_CONFLICT', 'A product field path overlaps a scalar value.');
    current = current[key];
